  'use strict';
  const E=window.CityCommandEngine,N=window.NavalControlEngine,$=id=>document.getElementById(id);
  const canonicalState=JSON.parse(JSON.stringify(window.CITY_COMMAND_DATA));
  let state=JSON.parse(JSON.stringify(canonicalState));
  const CITY_SAVE_KEY='american-revolution-slg/city-command/v0.49-city-damage-candidate';
  try{const saved=JSON.parse(localStorage.getItem(CITY_SAVE_KEY)||'null');if(saved?.schema_version===state.schema_version&&saved?.canonical_city_count===50)state=saved;}catch(_error){}
  // Geography and topology are canonical rules, not campaign progress. Always migrate old saves
  // to the bundled naval classification while preserving politics, armies and stockpiles.
  for(const [id,city] of Object.entries(canonicalState.cities))if(state.cities[id])state.cities[id].geography=JSON.parse(JSON.stringify(city.geography));
  state.topology=JSON.parse(JSON.stringify(canonicalState.topology));
  state.naval_city_classification=JSON.parse(JSON.stringify(canonicalState.naval_city_classification));
  state=N.ensureState(state);
  state=N.recalculateAll(state,'1775-06','初期海上情勢').state;
  E.recalculateCapacities(state,window.CITY_COMMAND_CONFIG);
  let selectedId=null,commandSourceId=null,activeCommand=null,targetId=null,resolvedCommand=null,selectedCommandCategory='military';
  let candidateIds=new Set(),candidateRoutes=new Map();
  const context={faction:'PATRIOT',controlled_sea_zones:['NORTH','CENTRAL','SOUTH']};
  const labels={PATRIOT:'独立派',BRITISH:'王党派',CONFLICT:'交戦中',UNCONTROLLED:'無支配',NORTH:'北部海域',CENTRAL:'中部海域',SOUTH:'南部海域'};
  const unrestLabels={CALM:'',UNREST:'不穏',UPRISING_IMMINENT:'蜂起寸前',REBELLION_ACTIVE:'反乱発生中'};
  const commandLabels={ATTACK:'攻撃',TRANSPORT:'輸送',MOVE:'部隊移動',OPINION:'世論工作'};
  const commandVariants={ATTACK:['ATTACK','LANDING_ATTACK'],TRANSPORT:['TRANSPORT_LAND','SEA_TRANSPORT'],MOVE:['MOVE','SEA_MOVE']};
