  const SUPPORT_BANDS=Object.freeze(window.CITY_COMMAND_CONFIG.support_bands.map(entry=>Object.freeze({...entry})));
  if(SEVEN_COLORS.length!==7||SUPPORT_BANDS.length!==7)throw new Error('SEVEN_LEVEL_DATA_INVALID');
  const logEntries=[];let pendingNavalOperation=null,selectedNavalZone='NORTH',selectedNavalBlockadeTarget=null,selectedNavalForeignTarget='NETHERLANDS';
  const NAVAL_STAGE_COLORS=Object.freeze(['#3F9FE8','#9BD8FF','#35C85A','#F3A6B8','#E9572F']);
  function navalStageColor(stage){const level=Number(stage?.level);return NAVAL_STAGE_COLORS[Number.isFinite(level)?Math.max(0,Math.min(4,level)):4];}
  function navalStageMarkup(stage,labelOverride=null){const label=labelOverride||stage?.label||'未確定';return `<span class="naval-stage-text" style="color:${navalStageColor(stage)}">${label}</span>`;}
  function persistCityState(){try{localStorage.setItem(CITY_SAVE_KEY,JSON.stringify(state));}catch(_error){}}

  function currentDate(){const calendar=window.__phase2UI?.getState?.().calendar;if(calendar)return`${calendar.year}年${calendar.month}月`;const offset=5+(state.elapsed_months||0),year=1775+Math.floor(offset/12),month=offset%12+1;return`${year}年${month}月`;}
  function currentPeriodKey(){const calendar=window.__phase2UI?.getState?.().calendar;return calendar?`${calendar.year}-${String(calendar.month).padStart(2,'0')}`:`1775-${String(6+(state.elapsed_months||0)).padStart(2,'0')}`;}
  function civilConsolidationUsed(cityId,faction=currentFaction()){const period=currentPeriodKey();return(state.civil_command_history||[]).some(x=>x.period===period&&x.city_id===cityId&&x.faction===faction&&['SECURITY','STOCKPILE_AID'].includes(x.command_type));}
