  function addLog(text,type='info',label='記録'){logEntries.push({date:currentDate(),text,type,label});if(logEntries.length>100)logEntries.shift();const el=$('game-log-scroll');el.replaceChildren(...logEntries.map(entry=>{const row=document.createElement('div');row.className=`log-entry ${entry.type}`;const date=document.createElement('div');date.className='log-date';date.textContent=entry.date;const heading=document.createElement('div');heading.className='log-label';heading.textContent=entry.label;const body=document.createElement('div');body.className='log-text';body.textContent=entry.text;row.append(date,heading,body);return row;}));el.scrollTop=el.scrollHeight;}
  function signed(v){return v>0?`+${v}`:v<0?String(v):'±0';}
  function meter(id,v){$(id).style.width=`${Math.max(0,Math.min(100,v))}%`;}
  function message(text,type=''){$('command-message').textContent=text;$('command-message').className=`command-message ${type}`;}
  function currentFaction(){const faction=window.__phase2UI?.getState?.().current_faction||context.faction||'PATRIOT';context.faction=faction;return faction;}
  function factionLabel(faction=currentFaction()){return faction==='PATRIOT'?'独立派':'王党派';}
