    const city=state.cities[change.city_id],faction=change.faction||currentFaction(),beforeLabel=change.before_label||supportBandLabel(change.before),afterLabel=change.after_label||supportBandLabel(change.after),bandChanged=beforeLabel!==afterLabel,cause=change.cause_label||'情勢の変化';
    if(!bandChanged)return null;
