    return{title:`${city.city_name}　独立支持の変化`,kindLabel:'現地副官 世論報告',layout:'report',faction,message,details:[{label:'変化の要因',value:cause},{label:'独立支持率',segments:[{text:`${change.before}％`,color:SEVEN_COLORS[supportBand(change.before)]},{text:' → '},{text:`${change.after}％`,color:SEVEN_COLORS[supportBand(change.after)]},{text:`（${signed(change.support_change)}）`,className:change.support_change>0?'delta-positive':'delta-negative'}]},{label:'支持段階',value:`${beforeLabel} → ${afterLabel}`,className:'warning'}]};
