  function navalOperationPreview(zoneId,type){const faction=currentFaction(),effect=type==='PATROL'?'中':type==='BLOCKADE'?'なし':'小';return{zone_id:zoneId,type,target_city_id:null,foreign_target:selectedNavalForeignTarget||'NETHERLANDS',control_effect:effect,html:`<strong>${N.ZONES[zoneId]}・${N.OPERATIONS[type].label}　制海権上昇：${navalControlRiseMarkup(effect)}</strong><br>${navalOperationDescription(type,faction)}`};}
  let navalOperationTyping=null,navalOperationDelay=null,navalOperationFullHTML='';
