  function typeNavalOperation(preview){clearNavalOperationTyping();const target=$('naval-operation-message'),holder=document.createElement('div');navalOperationFullHTML=navalOperationConfirmHTML(preview);holder.innerHTML=navalOperationFullHTML;const speechSource=holder.firstElementChild,speech=speechSource?.textContent||'',rest=speechSource?[...holder.children].slice(1):[];const speechNode=document.createElement('div');speechNode.className='routine-order-typewriter';target.replaceChildren(speechNode,...rest);let i=0;navalOperationDelay=setTimeout(()=>{navalOperationDelay=null;navalOperationTyping=setInterval(()=>{speechNode.textContent=speech.slice(0,++i);if(i>=speech.length){clearInterval(navalOperationTyping);navalOperationTyping=null;}},18);},ROUTINE_TYPEWRITER_DELAY);}
