  function closeNavalOperation(){if(pendingNavalOperation?.is_maintenance){finishMonthlyBlockade(false);return;}clearNavalOperationTyping();pendingNavalOperation=null;selectedNavalBlockadeTarget=null;$('naval-operation-modal').hidden=true;}
  function applyNavalSideEffect(preview){const faction=currentFaction(),effect={cooperation_changes:[],support_changes:[],resource_gain:null,budget_change:0,diplomacy_change:0};if(preview.type==='COASTAL_GUARD'||preview.type==='SHIPPING_DISRUPTION'){const targetFaction=preview.type==='COASTAL_GUARD'?faction:N.enemyFaction(faction),coopDelta=preview.type==='COASTAL_GUARD'?1:-1,supportDelta=faction==='PATRIOT'?1:-1;for(const city of Object.values(state.cities))if(city.geography?.sea_zone_id===preview.zone_id&&city.geography?.naval_class!=='INLAND'&&city.politics?.military_control===targetFaction){const before=city.politics.public_cooperation,beforeSupport=city.politics.independence_support;city.politics.public_cooperation=Math.max(0,Math.min(100,before+coopDelta));city.politics.independence_support=Math.max(0,Math.min(100,beforeSupport+supportDelta));effect.cooperation_changes.push({city_id:city.city_id,before,after:city.politics.public_cooperation});effect.support_changes.push({city_id:city.city_id,before:beforeSupport,after:city.politics.independence_support});}}if(preview.type==='PRIVATEERING'){let military=window.__phase2UI.getState();if(faction==='PATRIOT'){const ports=(N.portNetwork(state,preview.zone_id).PATRIOT||[]).map(id=>state.cities[id]).filter(Boolean);const distribute=(resource,amount)=>{let remaining=amount;const allocations=[];const ranked=ports.map(city=>({city,free:Math.max(0,Number(city.capacity?.[resource]||0)-Number(city.stockpile?.[resource]||0))})).filter(x=>x.free>0).sort((a,b)=>b.free-a.free||String(a.city.city_id).localeCompare(String(b.city.city_id)));for(const entry of ranked){if(remaining<=0)break;const stored=Math.min(entry.free,remaining);entry.city.stockpile[resource]+=stored;remaining-=stored;allocations.push({city_id:entry.city.city_id,city_name:entry.city.city_name,amount:stored});}return{resource,requested:amount,stored:amount-remaining,overflow:remaining,allocations};};const food=distribute('FOOD',120),materials=distribute('MATERIALS',80);effect.resource_gain={food:food.stored,materials:materials.stored,food_overflow:food.overflow,materials_overflow:materials.overflow,food_allocations:food.allocations,materials_allocations:materials.allocations};if(military.political_phase?.national_budget_value){const before=military.political_phase.national_budget_value.BRITISH;military.political_phase.national_budget_value.BRITISH=Math.max(0,before-2);effect.budget_change=military.political_phase.national_budget_value.BRITISH-before;if(window.__phase2UI?.getState?.().current_faction==='BRITISH')setTimeout(()=>window.__eventNotificationUI?.show?.([{title:'私掠活動による本国財政損失',kindLabel:'本国財政報告',layout:'report',faction:'BRITISH',message:'独立派の私掠船によって、本国の国庫・軍事予算に損害が発生しております',details:[]}]),0);}}else{const map=military.political_phase?.foreign_intervention?.PATRIOT;if(map){const before=Number(map[preview.foreign_target])||0;map[preview.foreign_target]=Math.max(0,before-3);effect.diplomacy_change=map[preview.foreign_target]-before;}}window.__phase2UI.setState(military);}return effect;}

  function executeNavalOperation(){if(!pendingNavalOperation)return;if(pendingNavalOperation.is_maintenance){finishMonthlyBlockade(true);return;}finishNavalOperationTyping();try{const preview=pendingNavalOperation,faction=currentFaction(),out=N.activateOperation(state,preview.zone_id,faction,preview.type,currentPeriodKey(),{target_city_id:preview.target_city_id});state=out.state;const effect=applyNavalSideEffect(preview);window.__phase2UI.spendNormalCommand(N.OPERATIONS[preview.type].label);window.__phase2UI.recordExternalAction({type:'NAVAL_OPERATION',operation_type:preview.type,zone_id:preview.zone_id,faction,target_city_id:preview.target_city_id||null,foreign_target:preview.foreign_target||null});syncFieldArmyConsumption();persistCityState();closeNavalOperation();renderNavalInfo();if(selectedId)renderCityInfo(selectedId);renderPolitical();const changed=effect.cooperation_changes.length?`、沿岸都市${effect.cooperation_changes.length}か所の民衆協力度・支持率が変化`:effect.resource_gain?(()=>{const r=effect.resource_gain,portNames=[...new Set([...(r.food_allocations||[]),...(r.materials_allocations||[])].map(x=>x.city_name))],overflow=(r.food_overflow||0)+(r.materials_overflow||0),where=portNames.length?`（${portNames.join('・')}港）`:'';return`、拿捕物資 食糧${r.food}・物資${r.materials}を搬入${where}${overflow?`、超過廃棄${overflow}`:''}`;})():effect.diplomacy_change?`、外国交渉進展${effect.diplomacy_change}`:'';addLog(`${N.ZONES[preview.zone_id]}で${N.OPERATIONS[preview.type].label}を実施${changed}。`,'result','海上作戦');const notices=navalNotifications(out.events);if(notices.length)window.__eventNotificationUI?.show(notices);message(`${N.OPERATIONS[preview.type].label}を実行しました`,'ok');}catch(error){message(`実行不可: ${navalErrorLabel(error.message)}`,'error');closeNavalOperation();renderNavalInfo();}}
