    const supportValue=c.politics.independence_support,band=supportBand(supportValue),opinion=$('city-support');opinion.innerHTML=`<span class="city-opinion-percent">${String(supportValue).padStart(2,'0')}％</span><span class="city-opinion-label">${E.supportLabel(supportValue,window.CITY_COMMAND_CONFIG)}</span>`;opinion.style.color=SEVEN_COLORS[band];
