  function reinforcementAttackTargets(origin){const military=window.__phase2UI?.getState?.(),faction=currentFaction(),edges=state.topology?.edges||[],originCity=state.cities?.[origin];if(!military)return[];const adjacent=id=>edges.some(e=>!String(e.type||'').startsWith('water_')&&e.counts_as_land_adjacency!==false&&((e.a===origin&&e.b===id)||(e.a===id&&e.b===origin)));const seaReach=id=>{const target=state.cities?.[id];return Boolean(window.NavalControlEngine?.isPortOperational?.(originCity)&&originCity?.geography?.sea_zone_id&&target?.geography?.is_coastal&&target?.geography?.sea_zone_id);};return Object.values(military.battles||{}).filter(b=>['active','awaiting_continuation'].includes(b.status)&&(b.history||[]).length>0&&[b.attacker_faction,b.defender_faction].includes(faction)&&(adjacent(b.city_id)||seaReach(b.city_id))).map(b=>b.city_id);}
