      if(naval){state=naval.city;window.__phase2UI.setState(naval.military);for(const item of naval.decisions)addLog(`${state.cities[item.city_id]?.city_name||item.city_id}港の封鎖を敵AIが${item.kept?'コマンド1を用いて継続':'解除'}。`,'event','港湾封鎖');}
      else window.__phase2UI.setState(special.state);
