  function renderCivilActionCommanders(){const host=$('civil-action-commanders');host.replaceChildren();civilActionCommanderId=null;for(const {army,commander} of civilArmiesAt(selectedId,currentFaction())){const b=document.createElement('button');b.className='civil-commander-choice';b.disabled=Boolean(army.acted_this_month);const stats=civilActionType==='REPAIR'?`補給 <strong style="color:${statColor(commander.stats.logistics)}">${commander.stats.logistics}</strong>　政治 <strong style="color:${statColor(commander.stats.politics)}">${commander.stats.politics}</strong>`:`人望 <strong style="color:${statColor(commander.stats.charisma)}">${commander.stats.charisma}</strong>　政治 <strong style="color:${statColor(commander.stats.politics)}">${commander.stats.politics}</strong>`;b.innerHTML=`<span>${commander.name}</span><span>${stats}</span>${army.acted_this_month?'<span class="acted-label">行動済</span>':''}`;if(!army.acted_this_month){b.onclick=()=>{civilActionCommanderId=commander.id;host.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderCivilActionNote();};if(!civilActionCommanderId){civilActionCommanderId=commander.id;b.classList.add('active');}}host.appendChild(b);}if(civilActionType==='SECURITY'){const none=document.createElement('button');none.className='civil-commander-choice';none.innerHTML='<span>指揮官なし</span>';none.onclick=()=>{civilActionCommanderId='NONE';host.querySelectorAll('button').forEach(x=>x.classList.remove('active'));none.classList.add('active');renderCivilActionNote();};host.appendChild(none);if(!civilActionCommanderId){civilActionCommanderId='NONE';none.classList.add('active');}}renderCivilActionNote();}
