    if(civilConsolidationUsed(selectedId)){message('この都市では今月すでに治安維持または備蓄分配を実行済みです','error');closeCivilAction();renderCivilAvailability(selectedId);return;}const score=commander?Math.round(commander.stats.charisma*.60+commander.stats.politics*.40):0,coop=commander?(score>=85?7:score>=65?6:score>=45?5:4):3,supportMag=commander?(score>=65?3:2):1,support=currentFaction()==='PATRIOT'?supportMag:-supportMag,beforeC=city.politics.public_cooperation,beforeS=city.politics.independence_support,afterC=Math.min(100,beforeC+coop),afterS=Math.max(0,Math.min(100,beforeS+support));$('civil-action-modal').hidden=true;const actedNote=commander?'<div class="routine-order-note">担当の将軍は今月行動済みになります。</div>':'',speech=`<div>${city.city_name}で治安維持を実施し、民衆の生活と往来を安定させ${currentFaction()==='PATRIOT'?'ますぜ':'ます'}。</div><div class="routine-order-summary"><div class="routine-order-row"><span>担当</span><strong>${commander?`${commander.name}　人望 ${commander.stats.charisma}　政治 ${commander.stats.politics}`:'指揮官なし'}</strong></div><div class="routine-order-row"><span>民衆協力度</span><strong>${beforeC} → ${afterC} <b class="positive">（+${afterC-beforeC}）</b></strong></div><div class="routine-order-row"><span>独立支持率</span><strong>${beforeS}% → ${afterS}% <b class="${afterS-beforeS>=0?'positive':'negative'}">（${signed(afterS-beforeS)}）</b></strong></div></div>${actedNote}`;const orderCityId=selectedId,orderFaction=currentFaction(),orderCommanderId=civilActionCommanderId;const ok=await confirmRoutineOrder(speech,'治安維持　実行確認',true);if(!ok){$('civil-action-modal').hidden=false;return;}let spent;try{if(selectedId!==orderCityId||currentFaction()!==orderFaction||civilActionCommanderId!==orderCommanderId||state.cities[orderCityId]!==city)throw new Error('CIVIL_ORDER_STALE');spent=prepareCivilCommandSpend(orderCityId,orderFaction,orderCommanderId,'SECURITY');}catch(error){message(`実行不可：${civilOrderError(error)}`,'error');closeCivilAction();renderCivilAvailability(selectedId);return;}city.politics.public_cooperation=afterC;ci